-- Tests authored before migration. Explicit outer transaction leaves no fixtures.
begin;
create temporary table wp17_ids(label text primary key,id uuid);
create temporary table wp17_saved(label text primary key,data jsonb);
create temporary table wp17_results(label text,passed boolean);
grant select,insert,update on wp17_ids,wp17_saved,wp17_results to authenticated;
create function pg_temp.wp17_check(label text,passed boolean) returns void language sql security invoker as $$insert into pg_temp.wp17_results values(label,coalesce(passed,false))$$;
create function pg_temp.wp17_error(label text,query text,expected text) returns void language plpgsql security invoker as $$declare caught text;begin begin execute query;exception when others then get stacked diagnostics caught=returned_sqlstate;end;perform pg_temp.wp17_check(label,caught=expected);end;$$;
create function pg_temp.wp17_id(label text) returns uuid language sql security invoker as $$select id from pg_temp.wp17_ids where wp17_ids.label=$1$$;
create function pg_temp.wp17_version() returns text language sql security invoker as $$select state_version from public.weddings where id=pg_temp.wp17_id('a')$$;
create function pg_temp.wp17_active() returns jsonb language sql security invoker as $$select jsonb_build_object('wedding',to_jsonb(w),'ceremonies',(select jsonb_agg(to_jsonb(c) order by c.id) from public.ceremonies c where c.wedding_id=w.id),'tasks',(select jsonb_agg(to_jsonb(t) order by t.id) from public.tasks t where t.wedding_id=w.id),'costs',(select jsonb_agg(to_jsonb(i) order by i.id) from public.cost_items i where i.wedding_id=w.id),'cash',(select jsonb_agg(to_jsonb(e) order by e.id) from public.cash_entries e where e.wedding_id=w.id)) from public.weddings w where w.id=pg_temp.wp17_id('a')$$;
insert into auth.users(id,email) values('17000000-0000-4000-8000-000000000001','wp17-a@example.invalid'),('17000000-0000-4000-8000-000000000002','wp17-b@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"17000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wp17_ids values('a',public.create_wedding('WP17 SQL synthetic','Test city'));
select public.save_draft_setup(pg_temp.wp17_id('a'),pg_temp.wp17_version(),'WP17 SQL synthetic','Test city',null,true,null,'[{"title":"Reception","guest_count":300}]');
insert into wp17_ids select 'ceremony',id from public.ceremonies where wedding_id=pg_temp.wp17_id('a');
reset role;
update wedding_private.ceremonies set venue_capacity=320 where id=pg_temp.wp17_id('ceremony') and wedding_id=pg_temp.wp17_id('a');
set local role authenticated;
select public.generate_draft(pg_temp.wp17_id('a'),pg_temp.wp17_version());
select public.activate_plan(pg_temp.wp17_id('a'),pg_temp.wp17_version(),true);
select public.finance_cost(pg_temp.wp17_id('a'),null,pg_temp.wp17_version(),'create',jsonb_build_object('title','Return gifts','ceremony_id',pg_temp.wp17_id('ceremony'),'pricing_basis','PER_GUEST','fixed_estimate_paise',null,'per_guest_rate_paise','15000'),false,null);
select public.finance_cost(pg_temp.wp17_id('a'),null,pg_temp.wp17_version(),'create',jsonb_build_object('title','Caterer','ceremony_id',pg_temp.wp17_id('ceremony'),'pricing_basis','FIXED','fixed_estimate_paise','20000000','per_guest_rate_paise',null),false,null);
insert into wp17_ids select 'caterer',id from public.cost_items where title='Caterer' and wedding_id=pg_temp.wp17_id('a');
select public.finance_cost(pg_temp.wp17_id('a'),pg_temp.wp17_id('caterer'),pg_temp.wp17_version(),'state','{"state":"COMMITTED","amount_paise":"20000000"}',true,null);
select public.finance_cash(pg_temp.wp17_id('a'),pg_temp.wp17_id('caterer'),null,pg_temp.wp17_version(),'post','{"kind":"PAYMENT","amount_paise":"5000000","occurred_on":"2026-10-27","note":null,"intent_key":"wp17-prior-payment"}',false,null);
select public.finance_cost(pg_temp.wp17_id('a'),null,pg_temp.wp17_version(),'create',jsonb_build_object('title','Unknown rate','ceremony_id',pg_temp.wp17_id('ceremony'),'pricing_basis','PER_GUEST','fixed_estimate_paise',null,'per_guest_rate_paise',null),false,null);
select public.finance_cost(pg_temp.wp17_id('a'),null,pg_temp.wp17_version(),'create',jsonb_build_object('title','Fixed decoration','ceremony_id',pg_temp.wp17_id('ceremony'),'pricing_basis','FIXED','fixed_estimate_paise','100000','per_guest_rate_paise',null),false,null);
select public.update_task(pg_temp.wp17_id('a'),null,pg_temp.wp17_version(),'add',jsonb_build_object('title','WP17 completed ceremony task','ceremony_id',pg_temp.wp17_id('ceremony'),'due_date','2026-10-01'),false,false);
insert into wp17_ids select 'completed',id from public.tasks where wedding_id=pg_temp.wp17_id('a') and title='WP17 completed ceremony task';
select public.update_task(pg_temp.wp17_id('a'),pg_temp.wp17_id('completed'),pg_temp.wp17_version(),'status','{"status":"COMPLETED"}',false,false);
insert into wp17_saved values('before',pg_temp.wp17_active());
insert into wp17_saved values('context',public.adapt_context(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),null));
select pg_temp.wp17_check('preview reads do not mutate active plan',pg_temp.wp17_active()=(select data from wp17_saved where label='before'));
select pg_temp.wp17_check('coherent context version equals captured plan',(select data->'wedding'->>'state_version' from wp17_saved where label='context')=pg_temp.wp17_version());
select pg_temp.wp17_check('snapshot capacity recorded320',(select data->'capacity'->>'value' from wp17_saved where label='context')='320');
select pg_temp.wp17_check('safe snapshot excludes private notes',not exists(select 1 from jsonb_array_elements((select data->'costs' from wp17_saved where label='context')) i where i ? 'contract_notes'));
insert into wp17_saved values('proposal',public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),pg_temp.wp17_version(),350,null));
insert into wp17_ids select 'proposal',(data->>'id')::uuid from wp17_saved where label='proposal';
select pg_temp.wp17_check('proposal is PENDING',(select data->>'status' from wp17_saved where label='proposal')='PENDING');
select pg_temp.wp17_check('old new are positive300350',(select data->>'old_guest_count' from wp17_saved where label='proposal')='300' and (select data->>'new_guest_count' from wp17_saved where label='proposal')='350');
select pg_temp.wp17_check('snapshot equals authoritative preview',(select data->'preview_snapshot' from wp17_saved where label='proposal')=(select data from wp17_saved where label='context'));
select pg_temp.wp17_check('creation leaves entire active plan unchanged',pg_temp.wp17_active()=(select data from wp17_saved where label='before'));
select pg_temp.wp17_check('duplicate save returns same pending proposal',(public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),pg_temp.wp17_version(),350,null)->>'id')=pg_temp.wp17_id('proposal')::text);
select pg_temp.wp17_check('money transport exact text',not exists(select 1 from jsonb_array_elements((select data->'costs' from wp17_saved where label='context')) i where i->>'title'='Return gifts' and jsonb_typeof(i->'per_guest_rate_paise')<>'string'));
select pg_temp.wp17_check('unknown rate remains JSONnull',exists(select 1 from jsonb_array_elements((select data->'costs' from wp17_saved where label='context')) i where i->>'title'='Unknown rate' and i->'per_guest_rate_paise'='null'::jsonb));
select pg_temp.wp17_check('committed terms retained',exists(select 1 from jsonb_array_elements((select data->'costs' from wp17_saved where label='context')) i where i->>'title'='Caterer' and i->>'commitment_paise'='20000000'));
select pg_temp.wp17_check('completed task snapshot preserved',exists(select 1 from jsonb_array_elements((select data->'tasks' from wp17_saved where label='context')) t where t->>'id'=pg_temp.wp17_id('completed')::text and t->>'status'='COMPLETED' and t->>'completed_at' is not null));
select pg_temp.wp17_error('zero new count refused',$$select public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),pg_temp.wp17_version(),0,null)$$,'22023');
select pg_temp.wp17_error('same count refused',$$select public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),pg_temp.wp17_version(),300,null)$$,'22023');
select pg_temp.wp17_error('huge capacity refused',$$select public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),pg_temp.wp17_version(),350,50001)$$,'22023');
select pg_temp.wp17_check('scenario capacity explicit not active write',public.adapt_context(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),310)->'capacity'='{"value":310,"source":"SCENARIO"}'::jsonb and (select venue_capacity from public.ceremonies where id=pg_temp.wp17_id('ceremony'))=320);
select pg_temp.wp17_check('reject returns REJECTED',public.adapt_reject(pg_temp.wp17_id('a'),pg_temp.wp17_id('proposal'))->>'status'='REJECTED');
select pg_temp.wp17_check('reject leaves all active records unchanged',pg_temp.wp17_active()=(select data from wp17_saved where label='before'));
select pg_temp.wp17_check('reject replay idempotent',public.adapt_reject(pg_temp.wp17_id('a'),pg_temp.wp17_id('proposal'))->>'status'='REJECTED');
select pg_temp.wp17_check('terminal snapshot unchanged',(select preview_snapshot from public.change_proposals where id=pg_temp.wp17_id('proposal'))=(select data from wp17_saved where label='context'));
select pg_temp.wp17_check('fresh proposal after rejection has new identity',(public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),pg_temp.wp17_version(),350,null)->>'id')<>pg_temp.wp17_id('proposal')::text);
select pg_temp.wp17_error('direct approval update denied',$$update public.change_proposals set status='APPLIED' where id=pg_temp.wp17_id('proposal')$$,'42501');
select pg_temp.wp17_error('direct guest bypass denied',$$update public.ceremonies set guest_count=350 where id=pg_temp.wp17_id('ceremony')$$,'42501');
select pg_temp.wp17_error('proposal deletion denied',$$delete from public.change_proposals where id=pg_temp.wp17_id('proposal')$$,'42501');
select pg_temp.wp17_error('direct snapshot rewrite denied',$$update public.change_proposals set preview_snapshot='{}' where id=pg_temp.wp17_id('proposal')$$,'42501');
select pg_temp.wp17_check('anonymous has no execute',not has_function_privilege('anon','public.adapt_propose(uuid,uuid,text,integer,integer)','execute') and not has_function_privilege('anon','public.adapt_reject(uuid,uuid)','execute'));
select pg_temp.wp17_check('internal snapshot cannot be called by client',not has_function_privilege('authenticated','wedding_private.adapt_snapshot(uuid,uuid,integer)','execute'));
select pg_temp.wp17_check('NOLOGIN mutator has no permanent CREATE',not has_schema_privilege('wedding_mutator','public','create') and not has_schema_privilege('wedding_mutator','wedding_private','create'));
select pg_temp.wp17_check('approved WP18 approval exists with narrow hardened privileges',
 exists(select 1 from pg_proc p join pg_roles r on r.oid=p.proowner
 where p.oid=to_regprocedure('public.adapt_approve(uuid,uuid)')
 and p.prosecdef and r.rolname='wedding_guest_approver' and not r.rolcanlogin and not r.rolbypassrls
 and p.proconfig @> array['search_path=""']
 and not has_function_privilege('anon',p.oid,'EXECUTE')
 and has_function_privilege('authenticated',p.oid,'EXECUTE')));
select set_config('request.jwt.claims','{"sub":"17000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into wp17_ids values('b',public.create_wedding('WP17 B synthetic','Test city'));
select public.save_draft_setup(pg_temp.wp17_id('b'),(select state_version from public.weddings where id=pg_temp.wp17_id('b')),'WP17 B synthetic','Test city',null,true,null,'[{"title":"Reception","guest_count":200}]');
insert into wp17_ids select 'bceremony',id from public.ceremonies where wedding_id=pg_temp.wp17_id('b');
select pg_temp.wp17_check('B cannot read A context',public.adapt_context(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),null) is null);
select pg_temp.wp17_check('B cannot read A proposal history',not exists(select 1 from public.change_proposals where wedding_id=pg_temp.wp17_id('a')));
select pg_temp.wp17_error('B cannot create A proposal',$$select public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),'0',350,null)$$,'42501');
select pg_temp.wp17_error('B cannot reject A proposal',$$select public.adapt_reject(pg_temp.wp17_id('a'),pg_temp.wp17_id('proposal'))$$,'42501');
select set_config('request.jwt.claims','{"sub":"17000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.wp17_error('forged B ceremony denied',$$select public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('bceremony'),pg_temp.wp17_version(),350,null)$$,'42501');
insert into wp17_saved values('oldversion',to_jsonb(pg_temp.wp17_version()));
select public.finance_cost(pg_temp.wp17_id('a'),pg_temp.wp17_id('caterer'),pg_temp.wp17_version(),'expected_refund','{"expected_refund_paise":"0"}',false,null);
select pg_temp.wp17_error('stale context refused without retryable40001',$$select public.adapt_propose(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),(select data#>>'{}' from wp17_saved where label='oldversion'),351,null)$$,'PT409');
select pg_temp.wp17_check('new context has consistent later version',public.adapt_context(pg_temp.wp17_id('a'),pg_temp.wp17_id('ceremony'),null)->'wedding'->>'state_version'=pg_temp.wp17_version());
select pg_temp.wp17_check('prior50000 payment unchanged',(select amount_paise from public.cash_entries where intent_key='wp17-prior-payment')='5000000');
reset role;
select jsonb_build_object('checks',jsonb_agg(jsonb_build_object('name',label,'passed',passed)),'total',count(*),'passed',count(*) filter(where passed),'failed',count(*) filter(where not passed)) as wp17_result from wp17_results;
rollback;
